    resource, connection_row, first_crawl, rows_for_webhook, tracking_id
):
    if DRY_RUN:
        return
    if resource.suppress_webhooks():
        return
    if resource.is_child_resource():
        # we could probably start sending these, but people haven't asked
        # would just have to implement the webhook_base_type method on child resources
        return
    if first_crawl:
        # don't send these on first crawl - just send historical sync completed when done
        return
    if not rows_for_webhook:
        return
    if connection_row.get("webhooks_disabled"):
        return

    # confirm that the org has a Svix endpoint set up before sending webhooks
    svix = SvixUtil()
    org_id = resource.integration.org_id
    org_endpoints = svix.retry_get_endpoints(org_id)
    if not org_endpoints:
        logger.error("Never got Svix endpoints, no webhooks sent")
        return
    if not org_endpoints.data:
        logger.info(f"No webhook endpoints for org {org_id}")
        return
    selected_filter_bases = set()
    all_filters = False
    for endpoint in org_endpoints.data:
        filter_types = endpoint.filter_types
        if filter_types is None:
            all_filters = True
            # if filter_types is None (not []) for any endpoint, that means the endpoint doesn't filter anything out
            # and this endpoint listens to all resources
            break
        for filter_type in filter_types or []:
            # these will be like "order.updated" or "product.updated" or "inbound-shipment.receipt.created"
