            filter_base = filter_type.split(".")[0]
            selected_filter_bases.add(filter_base)
    webhook_base_type = resource.webhook_base_type()
    if not all_filters and webhook_base_type not in selected_filter_bases:
        logger.info(
            f"No Svix endpoints with filter base {webhook_base_type}, no webhooks sent"
        )
        return

    webhook_payload = {
        "resource": resource,
        "data": rows_for_webhook,
        "tracking_id": tracking_id,
    }
    write_pickle_to_s3("webhook", webhook_payload, source="submitter")


