import re

def resolve_ours_theirs(path, take="theirs"):
    s = open(path).read()
    pattern = re.compile(
        r"<<<<<<< [^\n]*\n(.*?)\n?=======\n(.*?)>>>>>>> [^\n]*\n", re.S
    )
    def repl(m):
        return m.group(2) if take == "theirs" else (m.group(1) + "\n" if m.group(1) else "")
    out, n = pattern.subn(repl, s)
    open(path, "w").write(out)
    return n

