    # wait for the submitter to finish all tasks for this crawl window before advancing latest_data
    logger.info(f"Waiting for submit tasks to drain through {next_start}")
    deadline = now() + timedelta(seconds=SUBMIT_DRAIN_TIMEOUT)
    while now() < deadline:
        crawl_item = get_scheduler_row(connection_id, function_name)
        if crawl_item.get("latest_data") == next_start:
            return
        if should_update_latest_data(crawl_item):
            advance_latest_data(connection_id, function_name, crawl_item)
            return
        sleep(SUBMIT_DRAIN_POLL)
    raise PokedexException(
        f"Submit tasks did not drain through {next_start} in {SUBMIT_DRAIN_TIMEOUT}s",
        500,
        origin="trackstar",
    )


