def handle_scheduler_crawl_items(resource, pickle_id):
    connection_id = resource.integration.connection_id
    function_name = resource.get_function().__name__

    if STAGE == "dev":
        crawl_item = add_finished_task_if_started(
            connection_id, function_name, pickle_id
        )
        if crawl_item is None:
            logger.info(
                f"orphan submitter pickle {pickle_id}: not in tasks_started, skipping"
            )
            return False
    else:
        update_crawl_rsp = update_crawl_items(
            connection_id,
            function_name,
            {"submit": {"tasks_finished": {pickle_id}}},
        )
        crawl_item = update_crawl_rsp["Attributes"]
    clean_up_crawl_submit(crawl_item)
    if not should_update_latest_data(crawl_item):
        return False
    logger.info("All submit tasks finished, setting latest data")
    advance_latest_data(connection_id, function_name, crawl_item)
    # a windowed crawl advances latest_data per window and keeps going, so draining
    # one window is not the crawl finishing
    # .get while we wait for rows to populate the mark_complete - aug 27 2026
    return crawl_item["submit"].get("mark_complete", True)


