def test_submit_update_removes_a_field():
    from utils.boto import SUBMIT_REMOVE, generate_sync_dynamo_args

    update_expression, values, _ = generate_sync_dynamo_args(
        {"submit": {"set_latest_data": SUBMIT_REMOVE}}
