            "last_enqueued": None,
            "latest_heartbeat": None,
            "submit": {"tasks_started": set([""]), "tasks_finished": set([""])},
        }

        if not crawl_frequency:
            resource_type = function_to_resource_map.get(integration_type, {}).get(
